import base64,csv,gzip,hashlib,json,pathlib,re,subprocess,yaml
R=pathlib.Path('/home/err/spaces/foresight');D=pathlib.Path('/tmp/foresight-e0-continuation-20261020')
def sha(b):return hashlib.sha256(b).hexdigest()
before=json.load(open(D/'before.json'))
changed={'docs/stabilization/tracker.md','docs/stabilization/work-graph.json','docs/agile/kanban/stabilization-e0-reconstruct-the-authoritative-backlog-ation-e0.md'}
ledgers={'.ημ/receipts.edn','.ημ/session-mycology/ledger.md','.ημ/kanban-events/ledger.edn'}
for path,meta in before.items():
    b=(R/path).read_bytes()
    if path in changed:continue
    if path in ledgers:b=b[:meta['bytes']]
    assert sha(b)==meta['sha256'],('pre-existing bytes changed',path)
o=json.load(open(R/'docs/stabilization/e0-refresh.json'));ref=o['native_evidence'];b=(R/ref['path']).read_bytes();assert sha(b)==ref['sha256'];plain=gzip.decompress(b);assert sha(plain)==ref['uncompressed_sha256'];native=json.loads(plain)
old=json.load(open(R/'docs/stabilization/e0-work-graph.json'));rows={p['identity']:p for p in old['pull_requests']};curr={p['identity']:p for p in o['pull_requests']}
assert len(curr)==len(o['pull_requests'])==442 and curr.keys()==rows.keys()
assert sum(p['state']=='OPEN' for p in curr.values())==441
assert sum(p['state']=='MERGED' for p in curr.values())==1
assert len(o['changed_sources'])==6 and o['summary']['changed_open_head_or_base']==5
for k,p in curr.items():assert (p['frozen_head_sha'],p['frozen_base_sha'])==(rows[k]['head_sha'],rows[k]['base_sha']) and p['tested_merge_candidate'] is None
assert len(list(csv.DictReader(open(R/'docs/stabilization/e0-refresh.csv'))))==442
for p in o['recovered_source_custody']:
    b=(R/p['recovered_path']).read_bytes();assert sha(b)==p['sha256'];assert hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()==p['expected_blob_oid']==p['actual_blob_oid']
assert len(o['recovered_source_custody'])==4 and len({p['actual_blob_oid'] for p in o['recovered_source_custody']})==2
bs=native['knoxx_boundary'];assert bs['counts']=={'mailbox_delta_paths':32,'identity_same_blob_as_mailbox':32,'identity_differs_from_qualified331':32,'foundation375_differs_from_qualified331':0,'policy376_differs_from_qualified331':0}
assert not any(x['data']['truncated'] for x in bs['trees'].values())
for p in bs['path_observations']:
    nodes=p['nodes'];assert nodes['335']['sha']==nodes['333']['sha'];assert (nodes['335'] or {}).get('sha')!=(nodes['331'] or {}).get('sha')
    assert (nodes['375'] or {}).get('sha')==(nodes['376'] or {}).get('sha')==(nodes['331'] or {}).get('sha')
comp=native['knoxx_extra_native']['merged-source-ancestry']['data'];assert comp['behind_by']==0 and comp['merge_base_commit']['sha']==rows['riatzukiza/session-mycology#1']['head_sha']
assert len(native['details'])==7 and all(x['source_stable'] for x in native['details'].values())
assert sum(x['unresolved_threads'] for k,x in o['fresh_detail_summaries'].items() if k in curr and curr[k]['state']=='OPEN')==8
for x in native['details'].values():
    assert all(v['complete'] and len(v['pages'][-1]['data']['check_runs'] if k=='checks' else v['pages'][-1]['data'])<100 for k,v in x['evidence'].items())
    assert len(x['evidence']['files']['items'])==x['start']['data']['changed_files']
    assert not x['thread_pages'][-1]['response']['data']['repository']['pullRequest']['reviewThreads']['pageInfo']['hasNextPage']
assert len(o['consumer_pins']['index_gitlinks'])==23
nowpins=[]
for line in subprocess.check_output(['git','ls-files','--stage'],cwd=R,text=True).splitlines():
    meta,path=line.split('\t');mode,oid,stage=meta.split()
    if mode=='160000':nowpins.append({'path':path,'sha':oid,'stage':stage})
assert nowpins==o['consumer_pins']['index_gitlinks']
cards={}
for p in (R/'docs/agile/kanban').glob('*.md'):
    text=p.read_text()
    if text.startswith('---'):
        fm=yaml.safe_load(text.split('---',2)[1]);assert fm['uuid'] not in cards;cards[fm['uuid']]=fm
assert len(cards)==85 and cards['stabilization-e0']['status']=='breakdown' and cards['stabilization-e0']['assignee']=='codex'
assert all(cards['stabilization-e'+str(n)]['status']=='incoming' for n in range(1,8))
readback=json.load(open(D/'e0-readback.json'));assert readback['frontmatter']==cards['stabilization-e0']
def strings(x):
    if isinstance(x,str):yield x
    elif isinstance(x,dict):
        for v in x.values():yield from strings(v)
    elif isinstance(x,list):
        for v in x:yield from strings(v)
comment=(D/'e0-checkpoint-comment.txt').read_text().rstrip('\n');assert any(comment in s for s in strings(readback))
for name in ['e0-refresh.md','tracker.md']:
    p=R/'docs/stabilization'/name
    for link in re.findall(r'\]\(([^)]+)\)',p.read_text()):
        if '://' not in link:assert (p.parent/link.split('#')[0]).resolve().exists(),link
    assert all(s==s.rstrip() for s in p.read_text().splitlines())
subprocess.run(['git','diff','--check'],cwd=R,check=True,capture_output=True)
print('PASS 442 frozen identities and CSV rows; 441 open/1 merge; 5 open + 1 merged source changes; 7 complete stable native collections; 4 exact-ref custody recoveries/2 blobs; 32-path independent published-tree comparisons; merge ancestry; all23 consumer pins unchanged; all85 card identities/states; exact Rheos comment readback; untouched pre-existing file hashes and append-only ledger prefixes; snapshot digests; local links/whitespace.')
